\Statex{	extbf{Input:} A Graph $G$ with \dimension vertices, two vertices 
odeA and 
odeB with a multi-edge of multiplicity $m$ between them.}\Statex{	extbf{Output:} A Graph $G'$ with $\dimension+2m$ vertices}\State $V(G') \gets V(G) \cup \{i_{j,1}, i_{j,2} \;\vert\; j\in [m]\}$, where $i_{j,1},i_{j,2}
otin V(G)$\State $E(G') \gets E(G) \setminus \{\{
odeA, 
odeB\}\}$\State $E(G') \gets E(G') \cup \{\{
odeA, i_{j,1}\},\{i_{j,1}, i_{j,2}\},\{i_{j,2}, 
odeB\} \;\vert\; j\in [m]\}$\State \Return $G'$

